    if (!inst) return;
    const r = el.getBoundingClientRect();
    if (r.width <= 0 || r.height <= 0) return; // 跳过隐藏 / 未挂载的 chart
    const cx = r.left + r.width / 2;
    const cy = r.top + r.height / 2;
    ['mouseover', 'mousemove'].forEach(t => {
      try {
